[
  {
    "name": "林知夏（女）",
    "description": "女主角，曾经相爱的恋人，如今是独立干练的都市白领，在雨夜偶遇前任",
    "appearance": "28岁，长直黑发披肩，素颜略显苍白，眼神温柔但带着克制，鹅蛋脸，薄唇",
    "costume": "米白色高领针织衫，驼色长款风衣，黑色直筒西裤，黑色低跟皮鞋",
    "personality": "外表冷静克制，内心细腻柔软，理性却藏不住感性"
  },
  {
    "name": "陈屿（男）",
    "description": "男主角，曾经相爱的恋人，如今是温和内敛的建筑设计师，在雨夜为前任撑伞",
    "appearance": "30岁，短寸黑发微卷，眉目深邃，下颌线清晰，有淡淡黑眼圈，气质忧郁",
    "costume": "深灰色圆领羊绒毛衣，黑色长款风衣，深蓝色直筒牛仔裤，黑色马丁靴",
    "personality": "沉默寡言但深情，愿意为爱的人默默付出，不善表达"
  },
  {
    "name": "便利店店员",
    "description": "第1集末尾出现，作为背景人物烘托氛围",
    "appearance": "20岁出头，戴着便利店帽子，笑容明亮",
    "costume": "便利店制服",
    "personality": "活泼友善"
  }
]

[
  {
    "name": "老街转角",
    "description": "两人曾经约定见面的老地方，街角有一棵法国梧桐，下方有破旧电话亭",
    "visualStyle": "雨夜，昏黄路灯打湿地面反射霓虹，雾气弥漫，电影感强烈"
  },
  {
    "name": "深夜便利店",
    "description": "城市24小时便利店，玻璃门透出冷白灯光，雨水从玻璃滑落",
    "visualStyle": "冷色调荧光灯与外部暖黄路灯形成冷暖对比，雨痕玻璃投影"
  },
  {
    "name": "老式天桥",
    "description": "横跨马路的人行天桥，下方车流霓虹穿梭",
    "visualStyle": "湿润桥面反射车灯霓虹，远景城市天际线模糊"
  }
]

{
  "scenes": [
    {
      "location": "老街转角",
      "time": "夜晚·大雨",
      "characters": [
        "林知夏",
        "陈屿"
      ],
      "action": "林知夏撑透明伞匆匆走来，撞见独自站在梧桐树下的陈屿。陈屿缓缓转身，两人隔雨对望。",
      "dialogue": "陈屿：知夏？\n林知夏：（怔住）……陈屿？",
      "mood": "压抑、震惊、潮湿的怅惘"
    },
    {
      "location": "老街转角",
      "time": "夜晚·大雨",
      "characters": [
        "林知夏",
        "陈屿"
      ],
      "action": "陈屿沉默片刻，将黑伞缓缓倾向林知夏一侧，自己半边肩膀暴露在雨水中。两人共撑一伞，缓步走入雨巷。",
      "dialogue": "（雨声，无对白）",
      "mood": "克制深情、欲言又止"
    },
    {
      "location": "深夜便利店",
      "time": "夜晚·雨渐小",
      "characters": [
        "林知夏",
        "陈屿",
        "便利店店员"
      ],
      "action": "两人走到便利店玻璃门前停下，店员透过玻璃朝他们微笑。林知夏与陈屿在便利店灯下对视，千言万语哽在喉间。",
      "dialogue": "便利店店员：（推门）欢迎光临。\n陈屿：……你最近，还好吗？",
      "mood": "温暖、心酸、悬而未决"
    }
  ]
}
